TLM.f("Tempora/Pent04-1",{"officium":"Feria secunda infra Hebdomadam IV post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent04-0","from":{"Introitus":"Tempora/Pent04-0","Oratio":"Tempora/Pent04-0","Lectio":"Tempora/Pent04-0","Graduale":"Tempora/Pent04-0","Evangelium":"Tempora/Pent04-0","Offertorium":"Tempora/Pent04-0","Secreta":"Tempora/Pent04-0","Communio":"Tempora/Pent04-0","Postcommunio":"Tempora/Pent04-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 26:1; 26:2"},{"k":"text","la":"Dóminus illuminátio mea et salus mea, quem timebo? Dóminus defensor vitæ meæ, a quo trepidábo? qui tríbulant me inimíci mei, ipsi infirmáti sunt, et cecidérunt."},{"k":"ref","la":"Ps 26:3"},{"k":"text","la":"Si consístant advérsum me castra: non timébit cor meum."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dóminus illuminátio mea et salus mea, quem timebo? Dóminus defensor vitæ meæ, a quo trepidábo? qui tríbulant me inimíci mei, ipsi infirmáti sunt, et cecidérunt."}],"Oratio":[{"k":"text","la":"Da nobis, quǽsumus, Dómine: ut et mundi cursus pacífice nobis tuo órdine dirigátur; et Ecclésia tua tranquílla devotióne lætétur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 8:18-23"},{"k":"text","la":"Fratres: Exístimo, quod non sunt condígnæ passiónes hujus témporis ad futúram glóriam, quæ revelábitur in nobis. Nam exspectátio creatúræ revelatiónem filiórum Dei exspéctat. Vanitáti enim creatúra subjécta est, non volens, sed propter eum, qui subjécit eam in spe: quia et ipsa creatúra liberábitur a servitúte corruptiónis, in libertátem glóriæ filiórum Dei. Scimus enim, quod omnis creatúra ingemíscit et párturit usque adhuc. Non solum autem illa, sed et nos ipsi primítias spíritus habéntes: et ipsi intra nos gémimus, adoptiónem filiórum Dei exspectántes, redemptiónem córporis nostri: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 78:9; 78:10"},{"k":"text","la":"Propítius esto, Dómine, peccátis nostris: ne quando dicant gentes: Ubi est Deus eórum?"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter honórem nóminis tui, Dómine, líbera nos.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 9:5; 9:10"},{"k":"text","la":"Deus, qui sedes super thronum, et júdicas æquitátem: esto refúgium páuperum in tribulatióne. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 5:1-11"},{"k":"text","la":"In illo témpore: Cum turbæ irrúerent in Jesum, ut audírent verbum Dei, et ipse stabat secus stagnum Genésareth. Et vidit duas naves stantes secus stagnum: piscatóres autem descénderant et lavábant rétia. Ascéndens autem in unam navim, quæ erat Simónis, rogávit eum a terra redúcere pusíllum. Et sedens docébat de navícula turbas. Ut cessávit autem loqui, dixit ad Simónem: Duc in altum, et laxáte rétia vestra in captúram. Et respóndens Simon, dixit illi: Præcéptor, per totam noctem laborántes, nihil cépimus: in verbo autem tuo laxábo rete. Et cum hoc fecíssent, conclusérunt píscium multitúdinem copiósam: rumpebátur autem rete eórum. Et annuérunt sóciis, qui erant in ália navi, ut venírent et adjuvárent eos. Et venérunt, et implevérunt ambas navículas, ita ut pæne mergeréntur. Quod cum vidéret Simon Petrus, prócidit ad génua Jesu, dicens: Exi a me, quia homo peccátor sum, Dómine. Stupor enim circumdéderat eum et omnes, qui cum illo erant, in captúra píscium, quam céperant: simíliter autem Jacóbum et Joánnem, fílios Zebedǽi, qui erant sócii Simónis. Et ait ad Simónem Jesus: Noli timére: ex hoc jam hómines eris cápiens. Et subdúctis ad terram návibus, relictis ómnibus, secuti sunt eum."}],"Offertorium":[{"k":"ref","la":"Ps 12:4-5"},{"k":"text","la":"Illúmina óculos meos, ne umquam obdórmiam in morte: ne quando dicat inimícus meus: Præválui advérsus eum."}],"Secreta":[{"k":"text","la":"Oblatiónibus nostris, quǽsumus, Dómine, placáre suscéptis: et ad te nostras étiam rebélles compélle propítius voluntátes."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 17:3"},{"k":"text","la":"Dóminus firmaméntum meum, et refúgium meum, et liberátor meus: Deus meus, adjútor meus."}],"Postcommunio":[{"k":"text","la":"Mystéria nos, Dómine, quǽsumus, sumpta puríficent: et suo múnere tueántur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"fa6912dd86abf889":{"t":"Ps 26, 1 i 2, Ps 26, 3\n(Ps 26, 1 i 2) Gospodin mi je svjetlo i spas, koga da se bojim? Gospodin je branilac moga života, pred kim da strepim? Dušmani koji me muče smalaksali su i klonuli. (Ps 26, 3) Da se protiv mene i vojska utabori, neće se bojati moje srce.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 26, 1 i 2) Gospodin mi je svjetlo i spas, koga da se bojim? Gospodin je branilac moga života, pred kim da strepim? Dušmani koji me muče smalaksali su i klonuli."},"f8d0659aa5237e1d":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, Gospodine, i da se, prema tvojoj naredbi tok svijeta upravlja za naš mir i da tvoja Crkva uživa u nesmetanoj svetoj službi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"e7c08f8accb8300b":{"t":"Rim 8, 18-23\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo, držim da se patnje sadašnjega vremena ne mogu usporediti s budućom slavom koja će se objaviti u nama. I stvorovi željno očekuju objavljenje sinova Božjih. Stvorovi su podvrgnuti ispraznosti, ne po svojoj volji, nego po volji onoga koji ih je podvrgao, ali u nadi da će biti oslobođen od raspadljivosti, da postignu slavnu slobodu djece Božje. Znamo da svi stvorovi uzdišu i da se nalaze u porođajnim bolovima sve dosada. Ali ne samo oni nego i mi koji imamo prvine Duha, i mi uzdišemo u sebi i očekujemo Božje posinaštvo, otkupljenje našega tijela u Gospodinu našem Isusu Kristu."},"f6172450398af3b7":{"t":"Ps 78, 9 i 10\nBudi milostiv, Gospodine, grijesima našim. Zašto da govore narodi: Gdje je Bog njihov? Pomozi nam, Bože spasitelju naš, i radi slave imena svoga izbavi nas, Gospodine.\n\nPs 9, 5 i 10\n<i>Aleluja</i>, <i>aleluja</i>.\nBože, koji sjediš na prijestolju i sudiš pravo, budi utočište siromahu u nevolji. <i>Aleluja</i>."},"7e3b17d0d004fd3b":{"t":"Lk 5, 1-11\nSlijedi sveto Evanđelje po Luki. U ono vrijeme, kad je narod hrlio k Isusu, da čuje Božju riječ, on je stajao na obali Genezaretskoga jezera. I ugleda uz obalu dvije lađe, iz kojih su ribari bili izašli te su prali mreže. On uđe u jednu od tih lađa, koja je bila Šimunova, pa ga zamoli da malo otisne od kraja. Tada sjede i poče iz lađe učiti narod. – Kad je prestao govoriti, reče Petru: Povezi na pučinu i bacite mreže za ulov! Odgovori mu Šimun: Učitelju, mučili smo se svu noć i ništa nismo ulovili. Ali, na tvoju riječ bacit ću mrežu. Učine tako i zapašu mnogo riba, da im je mreža pucala. I pozovu ribare iz druge lađe da dođu i da im pomognu. I dođu, i napune se obje lađe, tako da su gotovo tonule. Kad to vidje Šimun Petar, padne na koljena pred Isusa i reče: Idi od mene, Gospodine, jer ja sam grješan čovjek! Strah je bio obuzeo njega i sve njegove drugove zbog riba koje su ulovili. Isto tako i Zebedejeve sinove, Jakova i Ivana, koji su bili Šimunovi drugovi. Tad Isus reče Šimunu: Nemoj se bojati, odsad ćeš loviti ljude! Oni izvuku lađe na kraj, ostave sve i pođu za njim."},"172c14d10345bb57":{"t":"Ps 12, 4-5\nProsvijetli oči moje da nikad ne zaspim na smrt, da ne kaže neprijatelj moj: Nadvladao sam ga."},"216555df044c1e27":{"t":"Primi naše prinose, molimo, Gospodine, kao pomirbeni dar pa i naše buntovne volje usmjeri k sebi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"cdfdea9a135d8132":{"t":"Ps 17, 3\nGospodin je stijena moja, tvrđava moja, osloboditelj moj, Bog moj, pomagač moj."},"bf7a2cbec5bf5888":{"t":"<i>Pomolimo se</i>.\nPrimljena otajstva, molimo, Gospodine, neka nas očiste i svojom snagom neka nas štite.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
